/**
 * Writes the tile tones and button edges from src/design-tokens/tile-tones.json
 * to the web (src/styles/tile-tones.generated.css) and the iPhone app
 * (AlphonsoTileTones.generated.swift), so both platforms use the same values.
 * src/lib/tile-tones.test.ts fails when either generated file is stale.
 *
 * Usage: bun scripts/export-design-tokens.ts
 */
import { writeFileSync } from "node:fs";

type Tone = { bg: string; ink: string };
type Palette = Record<string, Tone> & { edge: { moss: string; ember: string }; surface: string };
export type TileTokens = { tones: string[]; palettes: Record<string, unknown> };

const HEADER =
  "Generated by scripts/export-design-tokens.ts from src/design-tokens/tile-tones.json. Do not edit.";

// Web themes: Royal is :root; Meadow switches on data-palette (src/lib/theme.ts). The web takes the light
// values only; the "-dark" sets are for the apps in Dark Mode.
const WEB_SELECTORS: [string, string][] = [
  [":root", "royal"],
  [':root[data-palette="meadow"]', "meadow"],
];

function palette(tokens: TileTokens, key: string): Palette {
  return tokens.palettes[key] as Palette;
}

export function renderCss(tokens: TileTokens): string {
  const blocks = WEB_SELECTORS.map(([selector, key]) => {
    const p = palette(tokens, key);
    const lines = tokens.tones.flatMap((t) => [
      `  --tile-${t}-bg: ${p[t].bg};`,
      `  --tile-${t}-ink: ${p[t].ink};`,
    ]);
    lines.push(`  --edge-moss: ${p.edge.moss};`, `  --edge-ember: ${p.edge.ember};`);
    return `${selector} {\n${lines.join("\n")}\n}`;
  });
  return `/* ${HEADER} */\n\n${blocks.join("\n\n")}\n`;
}

function swiftColor(hex: string): string {
  return `Color(hex: 0x${hex.slice(1).toUpperCase()})`;
}

export function renderSwift(tokens: TileTokens): string {
  const keys = Object.keys(tokens.palettes);
  const entries = keys.map((key) => {
    const p = palette(tokens, key);
    const tones = tokens.tones
      .map((t) => `            .${t}: (${swiftColor(p[t].bg)}, ${swiftColor(p[t].ink)}),`)
      .join("\n");
    return `        "${key}": AlphonsoTileTonePalette(\n            tones: [\n${tones.replace(/^ {12}/gm, "                ")}\n            ],\n            edgeMoss: ${swiftColor(p.edge.moss)},\n            edgeEmber: ${swiftColor(p.edge.ember)}\n        ),`;
  });
  return `// ${HEADER}

import SwiftUI

/// The five tile colours. A tile's background and text colour follow the
/// active theme and its dark variant, like every other AlphonsoColor.
enum AlphonsoTileTone: String, CaseIterable {
${tokens.tones.map((t) => `    case ${t}`).join("\n")}

    var background: Color { AlphonsoTileTonePalette.current.tones[self]!.bg }
    var ink: Color { AlphonsoTileTonePalette.current.tones[self]!.ink }
}

struct AlphonsoTileTonePalette {
    let tones: [AlphonsoTileTone: (bg: Color, ink: Color)]
    let edgeMoss: Color
    let edgeEmber: Color

    static let all: [String: AlphonsoTileTonePalette] = [
${entries.join("\n")}
    ]

    /// Each theme ("royal", "meadow") adds "-dark" in Dark Mode.
    static var current: AlphonsoTileTonePalette {
        let manager = AlphonsoThemeManager.shared
        let key = manager.themeID.rawValue + (manager.systemColorScheme == .dark ? "-dark" : "")
        return all[key] ?? all["royal"]!
    }
}

extension AlphonsoColor {
    /// The darker bottom edge under a moss (primary) button.
    static var edgeMoss: Color { AlphonsoTileTonePalette.current.edgeMoss }
    /// The darker bottom edge under an ember button.
    static var edgeEmber: Color { AlphonsoTileTonePalette.current.edgeEmber }
}
`;
}

if (import.meta.main) {
  const tokens = (await import("../src/design-tokens/tile-tones.json")).default as TileTokens;
  writeFileSync("src/styles/tile-tones.generated.css", renderCss(tokens));
  writeFileSync(
    "ios/LearnWithAlphonso/Sources/DesignSystem/AlphonsoTileTones.generated.swift",
    renderSwift(tokens),
  );
  console.log("wrote tile tones for web and iOS");
}
